@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    --kbd-line: var(--ui-leading-md);
    --kbd-height: calc(var(--kbd-line) - 2px);
    --kbd-pad: 5px;

    display: inline-grid;
    justify-items: var(--kbd-align, center);
    align-items: center;
    font: inherit;
    white-space: nowrap;
  }

  /* `top`, not `middle`: middle centers on the x-height and makes the line taller. */
  .root[data-variant="caps"] {
    height: var(--kbd-line);
    vertical-align: top;
  }

  .root[data-size="sm"] {
    --kbd-line: var(--ui-leading-sm);
    --kbd-pad: 4px;
  }

  .spelling {
    grid-area: 1 / 1;
    display: inline-flex;
    min-width: 0;
  }

  /* Holds its width unseen until the platform stylesheet decides (see kbd.tsx). */
  .spelling[data-kbd-spelling="apple"] {
    visibility: hidden;
  }

  .keys {
    display: inline-flex;
    align-items: center;
    gap: 2px;
  }

  .key {
    display: inline-grid;
    place-items: center;
    box-sizing: border-box;
    /* A single key is a short pill, never a circle: the same shape as a
       button, just smaller. */
    min-width: calc(var(--kbd-height) * 1.5);
    height: var(--kbd-height);
    padding-inline: var(--kbd-pad);
    border-radius: var(--ui-radius-full);
    background: color-mix(in oklch, currentColor 7%, transparent);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    font-family: var(--ui-font-sans);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    font-style: normal;
    line-height: 1;
  }

  .root[data-variant="plain"] .keys {
    gap: 0;
    font-variant-numeric: tabular-nums;
  }

  @media (forced-colors: active) {
    .key {
      border: 1px solid CanvasText;
    }
  }
}

"use client";

import { useSyncExternalStore, type ComponentProps } from "react";
import styles from "./kbd.module.css";

type Platform = "apple" | "other";

/* [drawn, read] on Apple, then elsewhere. */
const KEYS: Record<string, [[string, string], [string, string]]> = {
  mod: [["⌘", "Command"], ["Ctrl", "Control"]],
  cmd: [["⌘", "Command"], ["⌘", "Command"]],
  ctrl: [["⌃", "Control"], ["Ctrl", "Control"]],
  alt: [["⌥", "Option"], ["Alt", "Alt"]],
  option: [["⌥", "Option"], ["Alt", "Alt"]],
  shift: [["⇧", "Shift"], ["Shift", "Shift"]],
  enter: [["↵", "Return"], ["↵", "Enter"]],
  return: [["↵", "Return"], ["↵", "Enter"]],
  backspace: [["⌫", "Delete"], ["⌫", "Backspace"]],
  delete: [["⌦", "Forward delete"], ["Del", "Delete"]],
  tab: [["Tab", "Tab"], ["Tab", "Tab"]],
  esc: [["esc", "Escape"], ["esc", "Escape"]],
  escape: [["esc", "Escape"], ["esc", "Escape"]],
  space: [["Space", "Space"], ["Space", "Space"]],
  up: [["↑", "Up arrow"], ["↑", "Up arrow"]],
  down: [["↓", "Down arrow"], ["↓", "Down arrow"]],
  left: [["←", "Left arrow"], ["←", "Left arrow"]],
  right: [["→", "Right arrow"], ["→", "Right arrow"]],
};

function key(name: string, platform: Platform): [string, string] {
  const known = KEYS[name.toLowerCase()];
  if (known) return known[platform === "apple" ? 0 : 1];
  const shown = name.length === 1 ? name.toUpperCase() : name;
  return [shown, shown];
}

/* Adds a <head> stylesheet before first paint that picks a spelling. Not an <html>
   attribute: hydration tolerates extra <head> nodes but reports attributes. */
const STYLE_ID = "kbd-platform";
const SCRIPT = `(function(){if(document.getElementById("${STYLE_ID}"))return;var a=/mac|iphone|ipad|ipod/i.test((navigator.userAgentData&&navigator.userAgentData.platform)||navigator.platform||navigator.userAgent),s=document.createElement("style");s.id="${STYLE_ID}";s.textContent="[data-kbd-spelling="+(a?"other":"apple")+"]{display:none!important}[data-kbd-spelling="+(a?"apple":"other")+"]{visibility:visible!important}";document.head.appendChild(s)})()`;

// Keep in sync with the test in SCRIPT.
function detect(): Platform {
  const nav = navigator as Navigator & { userAgentData?: { platform?: string } };
  // iPadOS reports itself as a Mac, which is right here: same keys.
  return /mac|iphone|ipad|ipod/i.test(nav.userAgentData?.platform || nav.platform || nav.userAgent) ? "apple" : "other";
}

// No stylesheet yet (script blocked, or no server Kbd): painted Kbds only change visibility.
if (typeof document !== "undefined" && !document.getElementById(STYLE_ID)) {
  const shown = detect();
  const hidden = shown === "apple" ? "other" : "apple";
  const painted = document.querySelector("[data-kbd-spelling]") !== null;
  const style = document.createElement("style");
  style.id = STYLE_ID;
  style.textContent =
    `[data-kbd-spelling=${hidden}]{${painted ? "visibility:hidden" : "display:none"}!important}` +
    `[data-kbd-spelling=${shown}]{visibility:visible!important}`;
  document.head.appendChild(style);
}

// True only for server HTML and hydration, where the script runs as parsed.
const subscribe = () => () => {};
const useServerHtml = () =>
  useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );

type KbdProps = Omit<ComponentProps<"kbd">, "children"> & {
  /** Keys pressed together, in order: `["mod", "K"]`. `mod` is ⌘ on Apple, Ctrl elsewhere. */
  keys: string[];
  /** `caps` (default) draws each key as a cap; `plain` is text only, like "⌘K" or "Ctrl+K". */
  variant?: "caps" | "plain";
  size?: "sm" | "md";
  /** Force one platform's spelling. */
  platform?: Platform;
};

/** A key or shortcut as the reader's keyboard labels it: ⌘K on Apple, Ctrl K elsewhere. */
export function Kbd({ keys, variant = "caps", size = "md", platform, className, ...props }: KbdProps) {
  const serverHtml = useServerHtml();

  const spell = (p: Platform) => {
    const parts = keys.map((k) => key(k, p));
    return {
      look: variant === "caps" ? parts.map(([shown]) => shown) : [parts.map(([shown]) => shown).join(p === "apple" ? "" : "+")],
      read: parts.map(([, read]) => read).join(" "),
    };
  };
  const apple = spell("apple");
  const other = spell("other");
  const same = apple.read === other.read && apple.look.join("\n") === other.look.join("\n");
  const both = !platform && !same;

  // Symbols like ⌘ are read inconsistently, so screen readers get key names instead.
  const spelling = ({ look, read }: ReturnType<typeof spell>, p?: Platform) => (
    <span key={p} className={styles.spelling} data-kbd-spelling={p}>
      <span className={styles.keys} aria-hidden="true">
        {variant === "caps"
          ? look.map((shown, i) => (
              <kbd key={i} className={styles.key}>
                {shown}
              </kbd>
            ))
          : look[0]}
      </span>
      <span className={styles.srOnly}>{read}</span>
    </span>
  );

  return (
    <>
      {both && serverHtml && <script dangerouslySetInnerHTML={{ __html: SCRIPT }} suppressHydrationWarning />}
      <kbd
        className={className ? `${styles.root} ${className}` : styles.root}
        data-variant={variant}
        data-size={size}
        {...props}
      >
        {both ? [spelling(apple, "apple"), spelling(other, "other")] : spelling(platform === "apple" ? apple : other)}
      </kbd>
    </>
  );
}
